<script setup lang="ts">definePageMeta({ middleware: 'auth' }); const route = useRoute(); const { find } = useStudents(); const { show } = useToasts(); const { data: student } = await useAsyncData(`edit-student-${route.params.id}`, () => find(Number(route.params.id))); async function saved(): Promise<void> { show('Student updated successfully.'); await navigateTo(`/students/${route.params.id}`) }</script>
<template><div v-if="student" class="page-shell"><PageHeader title="Edit student" :description="`Update ${student.first_name} ${student.last_name}'s profile.`" /><StudentForm :student="student" @saved="saved" /></div></template>
